<script setup lang="ts">
import {ref,computed} from 'vue'
import AppShell from '../components/AppShell.vue'
import MediaUploader from '../components/MediaUploader.vue'
import PrivateImage from '../components/PrivateImage.vue'
import EmptyState from '../components/EmptyState.vue'
import StatusPill from '../components/StatusPill.vue'
import {usePage} from '../composables/usePage'
import {get,mutate,authPost,currentPending,recoverOperation,type PendingOperation,ApiError} from '../services/api'
import {savedReceipts,saveReceipt,readReceipt,type ReceiptView} from '../services/privacy-receipts'
import {uuid,updateSession} from '../services/vault'
import {go} from '../services/navigation'
import {dateTime,label} from '../services/format'
import type {Profile,UploadItem,Context,Tokens,SessionView,Application,PageResult,PrivacyRequest,FamilyContext} from '../services/types'
const props=defineProps<{page:string;query:Record<string,string>}>()
const privacy=ref<{policyVersion:string;content:string;supportContact?:string}|null>(null),consent=ref(false),name=ref(''),avatar=ref<UploadItem[]>([]),profile=ref<Profile|null>(null),contexts=ref<Context[]>([]),familyName=ref(''),token=ref(''),purpose=ref('GUARDIAN_JOIN'),preview=ref<{purpose:string;familyName:string;childNickname?:string;expiresAt:string;canApply:boolean}|null>(null),applications=ref<Application[]>([]),pin=ref(''),newPin=ref(''),confirmPin=ref(''),recoveryCode=ref(''),enrollmentId=ref(''),recoverySaved=ref(false),localCode=ref(''),pinMode=ref(''),pending=ref<PendingOperation[]>([]),supportDescription=ref(''),supportRequest=ref<PrivacyRequest|null>(null),privacyRequests=ref<PrivacyRequest[]>([]),requestType=ref('EXPORT'),requestScope=ref('SELF_ACCOUNT'),confirmation=ref(''),requestNote=ref('')
const receiptViews=ref<ReceiptView[]>([]),receiptError=ref('')
async function loadReceipts(){receiptError.value='';const results=await Promise.allSettled(savedReceipts().map(readReceipt));receiptViews.value=results.filter((r):r is PromiseFulfilledResult<ReceiptView>=>r.status==='fulfilled').map(r=>r.value);if(results.some(r=>r.status==='rejected'))receiptError.value='部分回执暂时无法查询，请稍后重试。保存的回执仍保留在本设备。'}
let localAuth=false
// #ifdef H5
localAuth=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_AUTH==='true'
// #endif
const title=computed(()=>({login:'给努力一点回应',profile:'先让大家认出你',contexts:'回到你的家庭',invite:'接受家庭邀请',pin:'请家长验证',recovery:'确认这次操作',account:'我的账号',privacy:'隐私与数据'}[props.page]||'积乐圈'))
const {loading,error,busy,reload,act,session}=usePage(props.page,load,'public')
async function load(){
 if(['login','privacy','profile','account'].includes(props.page))privacy.value=await get('/public/privacy')
 if(props.page==='privacy')await loadReceipts()
 if(props.page==='login')return
 await session.bootstrap()
 if(props.page==='privacy'&&!session.view)return
 if(!session.view){go('login',{},true);return}
 if(props.page==='pin'){pinMode.value=props.query.purpose||'unlock';if(session.view.mode==='LOCKED'){const support=await get<PageResult<PrivacyRequest>>('/support/pin-recovery-requests');supportRequest.value=support.items[0]||null}return}
 if(['profile','account'].includes(props.page)){if(session.isDelegated){go('today',{},true);return}profile.value=await get<Profile>('/me/profile');name.value=profile.value.displayName||'';if(profile.value.avatarMediaId)avatar.value=[{localId:profile.value.avatarMediaId,mediaId:profile.value.avatarMediaId,status:'READY',progress:100}];return}
 if(!await session.guard(props.page==='recovery'?'authenticated':'account'))return
 if(props.page==='contexts'){contexts.value=await session.loadContexts();await loadApplications()}
 if(props.page==='invite'){token.value=props.query.token||token.value;purpose.value=props.query.purpose||'GUARDIAN_JOIN';if(token.value)await previewInvite()}
 if(props.page==='recovery')pending.value=currentPending()
 if(props.page==='privacy'){const result=await get<PageResult<PrivacyRequest>>('/me/privacy-requests');privacyRequests.value=result.items;requestScope.value=props.query.scope||'SELF_ACCOUNT'}
}
async function login(){await act(async()=>{if(!consent.value)throw new Error('请先阅读并同意隐私说明');if(localAuth&&!localCode.value.trim())throw new Error('请输入本地联调账号code');await session.login(localAuth?localCode.value.trim():undefined)})}
async function saveProfile(){await act(async()=>{if(!name.value.trim()||[...name.value.trim()].length>24)throw new Error('昵称需为1—24字');if(avatar.value.length!==1||avatar.value[0].status!=='READY'||!avatar.value[0].mediaId)throw new Error('请先成功上传一张头像');const result=await mutate<{profile:Profile;session:SessionView}>('PUT','/me/profile',{displayName:name.value.trim(),avatarMediaId:avatar.value[0].mediaId,privacyVersion:privacy.value?.policyVersion,expectedVersion:profile.value?.version||1},'保存头像与昵称');profile.value=result.profile;updateSession(result.session);if(props.page==='profile')await session.land();else uni.showToast({title:'资料已保存',icon:'none'})})}
async function createFamily(){await act(async()=>{const n=familyName.value.trim();if([...n].length<2||[...n].length>30)throw new Error('家庭名称需为2—30字');const created=await mutate<FamilyContext>('POST','/families',{name:n},'创建家庭');await session.loadContexts();const context=session.contexts.find(c=>c.family.id===created.family.id);if(context)await session.selectContext(context.contextId);else await session.land()})}
async function loadApplications(){const [a,b]=await Promise.all([get<PageResult<Application>>('/me/join-applications'),get<PageResult<Application>>('/me/child-binding-applications')]);applications.value=[...a.items.map(i=>({...i,purpose:'GUARDIAN_JOIN'})),...b.items.map(i=>({...i,purpose:'CHILD_BIND'}))]}
async function previewInvite(){preview.value=await authPost(purpose.value==='CHILD_BIND'?'/child-bindings/preview':'/invitations/preview',{token:token.value.trim()})}
async function applyInvite(){await act(async()=>{if(!preview.value?.canApply)throw new Error('邀请当前不可申请，请向负责人取得新邀请');await mutate('POST',purpose.value==='CHILD_BIND'?'/child-binding-applications':'/join-applications',{token:token.value.trim()},purpose.value==='CHILD_BIND'?'申请绑定孩子账号':'申请成为共同家长');go('contexts',{},true)},'申请已提交，等待负责人核对')}
async function withdraw(app:Application){await act(async()=>{await mutate('POST',`/${app.purpose==='CHILD_BIND'?'child-binding-applications':'join-applications'}/${app.id}/withdraw`,{expectedVersion:app.version},'撤回申请');await loadApplications()},'已撤回')}
async function prepareRecovery(){await act(async()=>{session.requireSettled();await session.login(await freshCode());go('pin',{purpose:'recover'},true)})}
function copyRecovery(){uni.setClipboardData({data:recoveryCode.value})}
async function pinSubmit(){await act(async()=>{
 if(pinMode.value==='enroll'){if(!/^\d{6}$/.test(newPin.value)||newPin.value!==confirmPin.value)throw new Error('请设置并重复输入相同的6位数字密码');const result=await authPost<{enrollmentId:string;recoveryCode:string}>('/auth/pin/enroll',{pin:newPin.value,confirmationPin:confirmPin.value});enrollmentId.value=result.enrollmentId;recoveryCode.value=result.recoveryCode;return}
 if(pinMode.value==='recover'){if(session.isDelegated)throw new Error('请先重新微信登录，再用恢复码重设家长密码');if(!recoveryCode.value.trim())throw new Error('请输入之前妥善保存的恢复码');if(!/^\d{6}$/.test(newPin.value)||newPin.value!==confirmPin.value)throw new Error('两次新密码必须为相同6位数字');const wxCode=await freshCode();const result=await authPost<Tokens&{recoveryCode:string}>('/auth/pin/recover',{newWechatCode:wxCode,recoveryCode:recoveryCode.value.trim(),newPin:newPin.value,confirmationPin:confirmPin.value,recoveryAttemptId:uuid()});session.accept(result);recoveryCode.value=result.recoveryCode;pinMode.value='recovered';return}
 if(pinMode.value==='change'){const result=await authPost<Tokens>('/auth/pin/change',{oldPin:pin.value,newPin:newPin.value,confirmationPin:confirmPin.value});session.accept(result);pinMode.value='unlock';pin.value='';return}
 if(!/^\d{6}$/.test(pin.value))throw new Error('请输入6位数字家长密码');const tokens=await authPost<Tokens>(pinMode.value==='exit'?'/auth/child-mode/exit':'/auth/pin/unlock',pinMode.value==='exit'?{pin:pin.value}:{pin:pin.value,targetContextId:props.query.contextId||undefined});session.accept(tokens);pin.value='';if(props.query.contextId)await session.selectContext(props.query.contextId);else await session.land()
 })}
async function enrollConfirm(){await act(async()=>{if(!recoverySaved.value)throw new Error('请先妥善保存恢复码并确认');await authPost('/auth/pin/enroll/confirm',{enrollmentId:enrollmentId.value,recoverySaved:true});recoveryCode.value='';if(props.query.childId)await session.enterChild(props.query.childId);else await session.land()})}
async function freshCode(){
 // #ifdef H5
 if(localAuth){if(!localCode.value.trim())throw new Error('本地联调需填写本次验证的微信code');return localCode.value.trim()}
 // #endif
 const result=await new Promise<UniApp.LoginRes>((resolve,reject)=>uni.login({provider:'weixin',success:resolve,fail:reject}));return result.code
}
async function support(){await act(async()=>{if(!supportDescription.value.trim())throw new Error('请描述需要帮助的情况，不要填写孩子证件或恢复码');supportRequest.value=await authPost('/support/pin-recovery-requests',{description:supportDescription.value.trim()})},'支持申请已提交')}
async function recover(op:PendingOperation){await act(async()=>{const result=await recoverOperation(op) as (PrivacyRequest&{receiptToken?:string})|undefined;if(op.path.endsWith('/privacy-requests')&&result?.receiptToken)saveReceipt({requestId:result.id,receiptToken:result.receiptToken,type:result.type,scope:result.scope});pending.value=currentPending();await session.bootstrap()},'操作已确认，请返回查看最新记录')}
async function requestPrivacy(){await act(async()=>{const scope=requestScope.value;const action=requestType.value+'_'+(scope==='FAMILY'?'FAMILY':'SELF');const expected=scope==='FAMILY'?session.family?.family.name:'本人账号';if(confirmation.value.trim()!==expected)throw new Error('请准确填写确认文字，确认你理解申请范围');const step=await authPost<{stepUpToken:string}>('/auth/step-up',{action,...(pin.value?{pin:pin.value}:{newWechatCode:await freshCode()})});const path=scope==='FAMILY'?`/families/${session.view?.familyId}/privacy-requests`:'/me/privacy-requests';const receipt=await mutate<PrivacyRequest&{receiptToken?:string}>('POST',path,{type:requestType.value,scope,confirmation:{confirmed:true,...(requestType.value==='DELETE'?(scope==='FAMILY'?{familyName:confirmation.value.trim(),deleteNonzeroBalancesConfirmed:true}:{deleteOwnChildSensitiveDataConfirmed:true}):{})},stepUpToken:step.stepUpToken},requestType.value==='EXPORT'?'申请数据导出':'申请数据删除');if(receipt.receiptToken)saveReceipt({requestId:receipt.id,receiptToken:receipt.receiptToken,type:receipt.type,scope:receipt.scope});confirmation.value='';pin.value='';await load()},'申请已提交，处理结果会显示在这里')}
async function download(req:PrivacyRequest){await act(async()=>{const grant=await authPost<{downloadUrl:string}>('/privacy-requests/'+req.id+'/download-grant',{});const result=await new Promise<UniApp.DownloadSuccessData>((resolve,reject)=>uni.downloadFile({url:grant.downloadUrl,success:resolve,fail:reject}));if(result.statusCode!==200)throw new Error('下载失败，请重新申请下载链接');
 // #ifdef MP-WEIXIN
 await new Promise<void>((resolve,reject)=>uni.shareFileMessage({filePath:result.tempFilePath,fileName:'积乐圈数据导出.zip',success:()=>resolve(),fail:reject}));
 // #endif
 // #ifdef H5
 uni.openDocument({filePath:result.tempFilePath,showMenu:true});
 // #endif
})}
const canProfileSave=computed(()=>avatar.value.length===1&&avatar.value[0].status==='READY'&&!!name.value.trim())
</script>
<template><AppShell :title="title" :public-page="['login','profile','pin'].includes(page)" :back="!['login','profile','contexts','pin'].includes(page)" :loading="loading" :error="error" @retry="reload">
<template v-if="page==='login'"><view class="hero"><text class="hero-title">一起约定，<br/>慢慢长大。</text><text class="hero-copy">完成日常的小事，积攒想要的奖励。家长和孩子都使用自己的微信身份，也可以由家长代办。</text></view><view class="check-row" @tap="consent=!consent"><checkbox :checked="consent" color="#176b5b"/><text>我已阅读并同意</text><button class="text-button" @tap.stop="go('privacy')">隐私说明</button></view><!-- #ifdef H5 --><view v-if="localAuth" class="field"><text class="field-label">本地联调微信 code</text><input class="input" v-model="localCode" placeholder="由本地API提供的测试身份code"/><text class="caption">仅本地H5编译显示，不进入微信生产包。</text></view><!-- #endif --><button :class="{'is-disabled':(busy)}" class="primary full" :loading="busy" :disabled="busy" @tap="login">微信登录</button><text class="caption section">首次登录须上传头像并填写昵称后才能访问家庭内容。</text></template>
<template v-else-if="page==='profile'||page==='account'"><view class="notice">头像可以是你喜欢的插画，不必是真人照片。昵称不要求实名。</view><MediaUploader v-model="avatar" :scope="{purpose:'USER_AVATAR'}" :max="1" avatar/><view class="field"><text class="field-label">昵称（必填）</text><input class="input" v-model="name" maxlength="24" placeholder="例如：妈妈、朵朵" type="nickname"/></view><button :class="{'is-disabled':(busy||!canProfileSave)}" class="primary full" :disabled="busy||!canProfileSave" :loading="busy" @tap="saveProfile">{{page==='profile'?'保存并继续':'保存资料'}}</button><template v-if="page==='account'"><view class="button-stack"><button class="secondary" @tap="go('contexts')">我已加入的家庭</button><button class="secondary" @tap="go('privacy')">个人隐私与数据申请</button><button class="secondary" @tap="act(()=>session.logout())">退出当前微信登录</button></view></template></template>
<template v-else-if="page==='contexts'"><view v-for="ctx in contexts" :key="ctx.contextId" class="card" @tap="act(()=>session.selectContext(ctx.contextId))"><view class="row between"><view><text class="card-title">{{ctx.family.name}}</text><text class="caption">{{label(ctx.relation)}}{{ctx.child?' · '+ctx.child.nickname:''}}</text></view><text class="status-pill">{{ctx.requiresPin&&ctx.relation!=='CHILD'?'需家长验证':'进入 →'}}</text></view></view><EmptyState v-if="!loading&&!contexts.length" title="先建立一个家庭约定" description="可以创建家庭，或接受负责人发来的邀请。"/><view class="card section"><text class="section-title">创建新的家庭</text><view class="field"><text class="field-label">家庭名称</text><input v-model="familyName" class="input" maxlength="30" placeholder="例如：向日葵之家"/></view><button :class="{'is-disabled':(busy)}" class="primary" :loading="busy" :disabled="busy" @tap="createFamily">创建家庭</button></view><view class="button-row"><button class="secondary" @tap="go('invite',{purpose:'GUARDIAN_JOIN'})">我收到家长邀请</button><button class="secondary" @tap="go('invite',{purpose:'CHILD_BIND'})">我收到孩子绑定邀请</button></view><view v-if="applications.length" class="section"><text class="section-title">我的申请</text><view v-for="a in applications" :key="a.id" class="card"><view class="row between"><text>{{a.familyName||'家庭申请'}}</text><StatusPill :status="a.status"/></view><text class="caption">{{a.purpose==='CHILD_BIND'?'孩子账号绑定':'加入共同家长'}} · {{dateTime(a.createdAt)}}</text><text v-if="a.reason" class="body-copy">{{a.reason}}</text><button v-if="['PENDING','PENDING_APPROVAL'].includes(a.status)" class="text-button" @tap="withdraw(a)">撤回申请</button></view></view><button class="text-button full section" @tap="act(()=>session.logout())">退出当前微信登录</button></template>
<template v-else-if="page==='invite'"><view class="notice">{{purpose==='CHILD_BIND'?'将自己的微信账号申请绑定到负责人指定的孩子档案。':'申请成为共同家长后，可管理家庭计划、审核和奖励。'}} 你的头像昵称将展示给负责人核对。</view><view class="field"><text class="field-label">邀请内容</text><textarea class="textarea" v-model="token" placeholder="粘贴负责人发来的邀请令牌"/></view><button :class="{'is-disabled':(busy)}" class="secondary full" :disabled="busy" @tap="act(previewInvite)">核对邀请</button><view v-if="preview" class="card section"><text class="section-title">{{preview.familyName}}</text><text v-if="preview.childNickname" class="body-copy">目标孩子：{{preview.childNickname}}</text><text class="caption">有效至 {{dateTime(preview.expiresAt)}}</text><button :class="{'is-disabled':(busy||!preview.canApply)}" class="primary full section" :disabled="busy||!preview.canApply" :loading="busy" @tap="applyInvite">{{purpose==='CHILD_BIND'?'申请绑定我的账号':'申请成为共同家长'}}</button><text v-if="!preview.canApply" class="field-error">此邀请已失效或暂不可使用，请联系负责人。</text></view></template>
<template v-else-if="page==='pin'"><view class="notice">{{pinMode==='exit'?'这是家长共用设备，验证后才能回到家长内容。':'家长密码保护家庭的管理权限。微信登录不能代替家长密码。'}}</view><template v-if="enrollmentId||pinMode==='recovered'"><text class="section-title">妥善保存你的恢复码</text><text class="caption section">恢复码只显示一次。忘记密码时需要它，不能仅靠微信登录重置。请保存到孩子无法访问的安全位置。</text><view class="code-box section">{{recoveryCode}}</view><button class="secondary full section" @tap="copyRecovery">复制恢复码</button><view class="check-row" @tap="recoverySaved=!recoverySaved"><checkbox :checked="recoverySaved" color="#176b5b"/><text>我已经妥善保存恢复码</text></view><button :class="{'is-disabled':(busy||!recoverySaved)}" v-if="enrollmentId" class="primary full" :disabled="busy||!recoverySaved" @tap="enrollConfirm">确认保存并继续</button><button :class="{'is-disabled':(!recoverySaved)}" v-else class="primary full" :disabled="!recoverySaved" @tap="recoveryCode='';pinMode='unlock'">已保存，验证新密码</button></template><template v-else><view v-if="['unlock','exit','change'].includes(pinMode)" class="field"><text class="field-label">{{pinMode==='change'?'原家长密码':'6位家长密码'}}</text><input v-model="pin" class="input pin-input" password type="number" maxlength="6" placeholder="••••••"/></view><view v-if="pinMode==='recover'" class="field"><text class="field-label">之前保存的恢复码</text><textarea v-model="recoveryCode" class="textarea" placeholder="输入一次性恢复码"/></view><template v-if="['enroll','change','recover'].includes(pinMode)"><view class="field"><text class="field-label">新的6位数字密码</text><input v-model="newPin" password type="number" class="input pin-input" maxlength="6"/></view><view class="field"><text class="field-label">再次输入新密码</text><input v-model="confirmPin" password type="number" class="input pin-input" maxlength="6"/></view></template><!-- #ifdef H5 --><view v-if="localAuth&&pinMode==='recover'" class="field"><text class="field-label">本地新微信验证 code</text><input class="input" v-model="localCode"/></view><!-- #endif --><button :class="{'is-disabled':(busy)}" class="primary full" :loading="busy" :disabled="busy" @tap="pinSubmit">{{pinMode==='enroll'?'设置家长密码':pinMode==='recover'?'验证恢复码并重设':'验证并继续'}}</button><button v-if="['unlock','exit'].includes(pinMode)" class="text-button full section" @tap="pinMode='recover';pin=''">忘记密码，使用恢复码</button><view v-if="pinMode==='recover'&&session.isDelegated" class="notice section">请先重新微信登录，进入锁定页面后再使用恢复码。重新登录不会直接获得家长权限。<button class="secondary full section" @tap="prepareRecovery">重新微信登录后恢复</button></view><view v-if="pinMode==='recover'&&session.view?.mode==='LOCKED'" class="section"><text class="section-title">恢复码也找不到了</text><text class="caption">不会自动解锁。支持人员会说明是否能在充分验证后处理，请勿提交孩子证件、学校或恢复码。</text><textarea class="textarea section" v-model="supportDescription" maxlength="500" placeholder="描述需要帮助的情况"/><button :class="{'is-disabled':(busy)}" class="secondary full section" :disabled="busy" @tap="support">提交支持申请</button><view v-if="supportRequest" class="notice section">申请 {{supportRequest.id}} · {{label(supportRequest.status)}}</view></view></template><button v-if="session.isDelegated" class="text-button full section" @tap="go('today',{},true)">返回孩子页面</button></template>
<template v-else-if="page==='recovery'"><view class="notice">这里记录发送后尚未确认的操作。查询会沿用原操作，不会再次创建兑换或重复发分。</view><view v-for="op in pending" :key="op.key" class="card"><text class="card-title">{{op.label}}</text><text class="caption">{{dateTime(op.createdAt)}}</text><text class="caption">操作号 {{op.key}}</text><button :class="{'is-disabled':(busy)}" class="primary full section" :loading="busy" :disabled="busy" @tap="recover(op)">查询这次操作</button></view><EmptyState v-if="!pending.length" title="没有待确认的操作" description="返回业务页面查看最新状态和余额。"/><button class="secondary full section" @tap="go(session.homeRoute(),{},true)">回到首页</button></template>
<template v-else-if="page==='privacy'"><view v-if="receiptViews.length||receiptError" class="section"><text class="section-title">本设备已保存的申请回执</text><text class="caption section">即使退出登录或账号已删除，也可查看最少处理状态。回执保存在本设备，不包含家庭内容；更换设备前请保留申请编号。</text><text v-if="receiptError" class="field-error">{{receiptError}}</text><view v-for="r in receiptViews" :key="r.requestId" class="card section"><view class="row between"><text>{{r.type==='DELETE'?'删除':'导出'}} · {{r.scope==='FAMILY'?'家庭':'本人账号'}}</text><StatusPill :status="r.status"/></view><text class="caption">申请编号 {{r.requestId}}</text><text class="body-copy">{{r.userVisibleNote}}</text><text v-if="r.onlineCompletedAt" class="caption">在线数据处理完成 {{dateTime(r.onlineCompletedAt)}}</text><text v-if="r.type==='DELETE'" class="caption">{{r.backupStatus==='COMPLETED'?'备份轮换清理已完成':r.backupStatus==='PENDING'?'在线处理已完成，备份仍等待最长35天轮换清理':'备份清理尚未开始'}}</text><text v-if="r.backupPurgeDueAt" class="caption">备份计划完成 {{dateTime(r.backupPurgeDueAt)}}</text><text v-if="r.backupCompletedAt" class="caption">备份实际完成 {{dateTime(r.backupCompletedAt)}}</text><text v-if="r.supportContact" class="caption">支持渠道 {{r.supportContact}}</text></view><button class="secondary full" @tap="act(loadReceipts)">刷新保存的回执</button></view><view class="card"><text class="section-title">隐私说明</text><text class="caption">版本 {{privacy?.policyVersion}}</text><text class="body-copy" style="white-space:pre-wrap">{{privacy?.content}}</text><text v-if="privacy?.supportContact" class="caption section">支持渠道：{{privacy.supportContact}}</text></view><template v-if="session.view&&session.canAccount&&session.view.mode!=='PROFILE_ONLY'&&session.view.mode!=='LOCKED'"><view class="card"><text class="section-title">数据处理申请</text><view class="tabs"><button :class="{active:requestType==='EXPORT'}" @tap="requestType='EXPORT'">导出数据</button><button :class="{active:requestType==='DELETE'}" @tap="requestType='DELETE'">删除数据</button></view><view class="chip-row"><button class="chip" :class="{active:requestScope==='SELF_ACCOUNT'}" @tap="requestScope='SELF_ACCOUNT'">仅本人账号</button><button v-if="session.isOwner" class="chip" :class="{active:requestScope==='FAMILY'}" @tap="requestScope='FAMILY'">本家庭全量</button></view><view class="notice warning">{{requestType==='DELETE'?'删除与归档不同。负责人删除个人账号前，必须转让相关家庭或先完成相应家庭在线数据删除。家庭删除须先归档，并删除包括非零积分在内的全部记录。删除本人账号会清理本人孩子的敏感文字和照片，共同账务去标识化保留。':'导出通常24小时内生成，最多3个自然日；下载文件保留7天。个人申请不包含其他孩子的私有资料。'}}</view><view class="field"><text class="field-label">确认申请范围</text><input class="input" v-model="confirmation" :placeholder="requestScope==='FAMILY'?'输入家庭名称确认':'输入“本人账号”确认'"/></view><view class="field"><text class="field-label">家长密码（如已设置）</text><input v-model="pin" class="input" password type="number" maxlength="6"/></view><!-- #ifdef H5 --><view v-if="localAuth" class="field"><text class="field-label">无PIN账号的本地微信验证code</text><input class="input" v-model="localCode"/></view><!-- #endif --><button :class="[requestType==='DELETE'?'danger-button full':'primary full', {'is-disabled':(busy)}]" :loading="busy" :disabled="busy" @tap="requestPrivacy">提交{{requestType==='DELETE'?'删除':'导出'}}申请</button></view><text class="section-title section">申请进度</text><view v-for="r in privacyRequests" :key="r.id" class="card section"><view class="row between"><text>{{r.type==='EXPORT'?'数据导出':'数据删除'}} · {{r.scope==='FAMILY'?'家庭':'个人'}}</text><StatusPill :status="r.status"/></view><text class="caption">提交 {{dateTime(r.requestedAt)}}<br/>预计处理 {{dateTime(r.dueAt)}}</text><text v-if="r.userVisibleNote" class="body-copy">{{r.userVisibleNote}}</text><button v-if="r.downloadAvailable" class="secondary full section" @tap="download(r)">下载并保存导出文件</button></view></template></template>
</AppShell></template>
